import React, { useState, useEffect } from "react";


import { CSSTransition } from "react-transition-group";
import {Link} from "gatsby";
import gridColours from "../data/grid-colours.json";

interface IProps {}

function Header(props: IProps) {
  const [showMenu, setShowMenu] = useState(false);

  // Dynamic favicon — random accent dots on each page load
  useEffect(() => {
    const colours = [...gridColours]
    for (let i = colours.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1))
      ;[colours[i], colours[j]] = [colours[j], colours[i]]
    }

    const size = 32
    const canvas = document.createElement('canvas')
    canvas.width = size
    canvas.height = size
    const ctx = canvas.getContext('2d')
    if (!ctx) return

    const dotCount = 7
    const dotRadius = 2
    const totalWidth = dotCount * (dotRadius * 2) + (dotCount - 1) * 1.5
    const startX = (size - totalWidth) / 2 + dotRadius
    const y = size / 2

    for (let i = 0; i < dotCount; i++) {
      ctx.fillStyle = colours[i % colours.length]
      ctx.beginPath()
      ctx.arc(startX + i * (dotRadius * 2 + 1.5), y, dotRadius, 0, Math.PI * 2)
      ctx.fill()
    }

    let link = document.querySelector("link[rel='icon']") as HTMLLinkElement
    if (!link) {
      link = document.createElement('link')
      link.rel = 'icon'
      document.head.appendChild(link)
    }
    link.href = canvas.toDataURL('image/png')
  }, []);

  const toggleHamburger = () => {
    setShowMenu(!showMenu);
  };

  const renderHamburger = () => {
    if (!showMenu) {
      return (
        <div className="hamburgerContainer" onClick={toggleHamburger} role="button" aria-expanded={false} aria-label="Open menu">
          <div className="burgerLine"></div>
          <div className="burgerLine"></div>
          <div className="burgerLine"></div>
        </div>
      );
    } else if (showMenu) {
      return (
        <div className="hamburgerContainer" onClick={toggleHamburger} role="button" aria-expanded={true} aria-label="Close menu">
          <div className="burgerLineRight">
            <div className="burgerLineLeft"></div>
          </div>
        </div>
      );
    }
  };

  const RenderMobileMenu = () => {
    return (
      <CSSTransition
        in={showMenu}
        timeout={500}
        classNames="mobNav"
        unmountOnExit
        onEnter={() => setShowMenu(true)}
      >
        <div className="mobMenuBg">
          <Link className="navLinkMob" to={"/"}>
            <div className="navTxt">Home</div>
          </Link>
          <Link className="navLinkMob" to={"/creations"}>
              <div className="navTxt">Creations</div>
          </Link>
           <Link className="navLinkMob" to={"/code"}>
              <div className="navTxt">Code</div>
          </Link>
           <Link className="navLinkMob" to={"/photography"}>
              <div className="navTxt">Photography</div>
            </Link>
          {/* <Link className="navLinkMob" to={"/photo-journeys"}>
              <div className="navTxt">Photo Journeys</div>
          </Link> */}
          {/* <Link className="navLinkMob" to={"/photo-grid"}>
              <div className="navTxt">Photo Grid</div>
          </Link> */}
          <Link className="navLinkMob" to={"/about"}>
            <div className="navTxt">My Story</div>
          </Link>
        </div>
      </CSSTransition>
    );
  };

  const renderNavMenu = () => {
    return (
      <div className="navContainer">
        <div className="navMenuHolder">
          <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/"}>
            <div className="navMenuTxt">Home</div>
          </Link>
           <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/creations"}>
              <div className="navMenuTxt">Creations</div>
          </Link>
          <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/code"}>
              <div className="navMenuTxt">Code</div>
          </Link>
           <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/photography"}>
              <div className="navMenuTxt">Photography</div>
            </Link>
           {/* <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/photo-journeys"}>
              <div className="navMenuTxt">Photo Journeys</div>
            </Link> */}
           {/* <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/photo-grid"}>
              <div className="navMenuTxt">Photo Grid</div>
            </Link> */}
              <Link className="navLink" getProps={({ isCurrent }) => isCurrent ? { className: "navLink active" } : {}} to={"/about"}>
            <div className="navMenuTxt">My Story</div>
          </Link>
        </div>
        {renderHamburger()}
      </div>
    );
  };

  return (
    <div>
      <div className="main-header">
        <div className="main-header__navLogo">
          <Link className="navLink nav-home-icon" to={"/"} aria-label="Home">
            <span className="home-dot"></span>
          </Link>
          <span className="nav-tagline">Capture · Create · Design</span>
          {renderNavMenu()}
        </div>
        {RenderMobileMenu()}
      </div>
    </div>
  );
}

export default Header;
